const event = $('Claim Due Events').item.json;
const task = $('Get Task — Inbound').item.json;
const dialog = $('Get Dialog — Inbound').item.json;

const runtime = $json;

function asArray(v) {
  if (Array.isArray(v)) return v;

  if (typeof v === 'string') {
    try {
      const parsed = JSON.parse(v);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  return [];
}

const messages = asArray(runtime.recent_messages);
const facts = asArray(runtime.active_facts);
const ownerRequests = asArray(runtime.open_owner_requests);

const conversationText = messages
  .map(m => {
    const who =
      m.sender_type === 'user'
        ? 'СОБЕСЕДНИК'
        : (
            m.sender_type === 'agent'
              ? 'АССИСТЕНТ'
              : String(m.sender_type ?? '').toUpperCase()
          );

    const body =
      String(m.text ?? '').trim() ||
      `[${m.message_type ?? 'message'}]`;

    return `${who}: ${body}`;
  })
  .join('\n');

const factsText =
  facts.length
    ? facts
        .map(f => {
          const cat =
            f.category
              ? `[${f.category}] `
              : '';

          return `- ${cat}${f.fact_text}`;
        })
        .join('\n')
    : '(подтверждённых фактов пока нет)';

const ownerText =
  ownerRequests.length
    ? ownerRequests
        .map(r => `- ${r.question}`)
        .join('\n')
    : '(открытых вопросов владельцу нет)';

return [{
  json: {
    ...event,

    agent_event: 'process_inbound',

    task_name: task.Name_task ?? '',
    goal: task.goal ?? '',
    required_result: task.required_result ?? '',
    assistant_role: task.assistant_role ?? '',
    assistant_identity: task.assistant_identity ?? '',
    information_base: task.information_base ?? '',
    rules: task.rules ?? '',
    communication_style: task.communication_style ?? '',

    person_name: dialog.person_name ?? event.person_name ?? '',
    person_role: dialog.person_role ?? event.person_role ?? '',
    person_context: dialog.person_context ?? '',

    conversation_text:
      conversationText ||
      '(история пуста)',

    facts_text: factsText,

    waiting_for_text:
      event.waiting_for ?? '',

    open_owner_requests_text:
      ownerText,

    allowed_actions:
      'send_message | ask_owner | complete_dialog'
  }
}];

