function parse(value) {
  if (value === null || value === undefined) {
    throw new Error('Agent Core returned empty response');
  }

  if (typeof value === 'object') {
    return value;
  }

  const cleaned =
    String(value)
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

  try {
    return JSON.parse(cleaned);
  } catch {
    const a = cleaned.indexOf('{');
    const b = cleaned.lastIndexOf('}');

    if (a === -1 || b === -1) {
      throw new Error(`No JSON in Agent Core response: ${cleaned}`);
    }

    return JSON.parse(cleaned.slice(a, b + 1));
  }
}

let raw =
  $json.output ??
  $json.response ??
  $json.text ??
  $json;

let parsed = parse(raw);

if (
  parsed.output !== undefined &&
  parsed.action === undefined
) {
  parsed = parse(parsed.output);
}

const action =
  String(parsed.action ?? '').trim();

if (
  action !== 'send_message' &&
  action !== 'ask_owner' &&
  action !== 'no_action' &&
  action !== 'complete_dialog'
) {
  throw new Error(`Unsupported Agent Core action: ${action}`);
}

const event =
  $('Claim Due Events').item.json;

const result = {
  ...event,
  action
};

if (action === 'send_message') {
  const message =
    String(parsed.message ?? '').trim();

  if (!message) {
    throw new Error('send_message has empty message');
  }

  let waitForUser =
    parsed.wait_for_user === true;

  if (
    event.event_type === 'start_dialog' ||
    event.event_type === 'followup'
  ) {
    waitForUser = true;
  }

  let waitingFor =
    String(parsed.waiting_for ?? '').trim();

  if (
    waitForUser &&
    !waitingFor
  ) {
    waitingFor =
      String(event.waiting_for ?? '').trim() ||
      'ответ собеседника';
  }

  if (!waitForUser) {
    waitingFor = '';
  }

  result.message = message;
  result.wait_for_user = waitForUser;
  result.waiting_for = waitingFor;
}

if (action === 'ask_owner') {
  if (event.event_type !== 'process_inbound') {
    throw new Error(
      `ask_owner is not allowed for event_type=${event.event_type}`
    );
  }

  const question =
    String(parsed.owner_question ?? '').trim();

  if (!question) {
    throw new Error('ask_owner has empty owner_question');
  }

  const message =
    String(parsed.message ?? '').trim();

  if (!message) {
    throw new Error(
      'ask_owner must include a user-facing message'
    );
  }

  const waitForUser =
    parsed.wait_for_user === true;

  let waitingFor =
    String(parsed.waiting_for ?? '').trim();

  if (waitForUser && !waitingFor) {
    waitingFor = 'ответ собеседника';
  }

  if (!waitForUser) {
    waitingFor = '';
  }

  result.message = message;
  result.wait_for_user = waitForUser;
  result.waiting_for = waitingFor;

  result.owner_question = question;
  result.owner_context =
    String(parsed.owner_context ?? '').trim();

  let answerScope =
    String(parsed.answer_scope ?? 'dialog')
      .trim()
      .toLowerCase();

  if (
    answerScope !== 'task' &&
    answerScope !== 'dialog'
  ) {
    answerScope = 'dialog';
  }

  result.answer_scope = answerScope;
}

if (action === 'no_action') {
  if (event.event_type !== 'followup') {
    throw new Error(
      `no_action is allowed only for followup, got ${event.event_type}`
    );
  }

  result.reason =
    String(parsed.reason ?? '').trim();

  result.clear_waiting =
    parsed.clear_waiting === true;
}


if (action === 'complete_dialog') {
  if (event.event_type !== 'process_inbound') {
    throw new Error(
      `complete_dialog is allowed only for process_inbound, got ${event.event_type}`
    );
  }

  const summary =
    String(parsed.summary ?? '').trim();

  const finalResult =
    String(parsed.final_result ?? '').trim();

  if (!summary) {
    throw new Error('complete_dialog has empty summary');
  }

  if (!finalResult) {
    throw new Error('complete_dialog has empty final_result');
  }

  const allowedReasons =
    new Set([
      'goal_achieved',
      'declined',
      'stop_requested',
      'not_relevant',
      'other'
    ]);

  let completionReason =
    String(parsed.completion_reason ?? 'other').trim();

  if (!allowedReasons.has(completionReason)) {
    completionReason = 'other';
  }

  result.message =
    String(parsed.message ?? '').trim();

  result.summary = summary;
  result.final_result = finalResult;
  result.completion_reason = completionReason;
}

return [{ json: result }];

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}

function bigint(v, label) {
  const s = String(v ?? '').trim();
  if (!/^-?\d+$/.test(s)) {
    throw new Error(`${label} is not an integer: ${s}`);
  }
  return s;
}

function optionName(v) {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v.name ?? String(v);
  }
  return String(v ?? '');
}

function multiNames(v) {
  if (!Array.isArray(v)) return [];
  return v.map(optionName).filter(Boolean);
}

function hhmm(v, fallback) {
  const m = String(v || fallback).match(/^(\d{1,2}):(\d{2})/);
  if (!m) throw new Error(`Invalid time: ${v}`);
  return { h: Number(m[1]), m: Number(m[2]) };
}

function addWorkingMinutes(task, minutes) {
  minutes = Math.max(0, Math.floor(Number(minutes || 0)));
  if (minutes <= 0) return null;

  const zone =
    optionName(task.timezone) ||
    'Europe/Moscow';

  const daysRaw =
    multiNames(task.work_days);

  const days =
    daysRaw.length
      ? daysRaw
      : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];

  const dayMap = {
    Mon: 1, Tue: 2, Wed: 3, Thu: 4,
    Fri: 5, Sat: 6, Sun: 7
  };

  const allowed =
    new Set(
      days
        .map(x => dayMap[x])
        .filter(Boolean)
    );

  const start = hhmm(task.work_start, '09:00');
  const end = hhmm(task.work_end, '19:00');

  let cursor = $now.setZone(zone);
  let remaining = minutes;

  for (let guard = 0; guard < 500 && remaining > 0; guard++) {
    let segment = null;

    for (let offset = -1; offset <= 370; offset++) {
      const day =
        cursor
          .startOf('day')
          .plus({ days: offset });

      if (!allowed.has(day.weekday)) {
        continue;
      }

      let ws =
        day.set({
          hour: start.h,
          minute: start.m,
          second: 0,
          millisecond: 0
        });

      let we =
        day.set({
          hour: end.h,
          minute: end.m,
          second: 0,
          millisecond: 0
        });

      if (we <= ws) {
        we = we.plus({ days: 1 });
      }

      if (we <= cursor) {
        continue;
      }

      const from =
        cursor > ws
          ? cursor
          : ws;

      if (from < we) {
        segment = {
          from,
          to: we
        };
        break;
      }
    }

    if (!segment) {
      throw new Error(
        'Could not find next working window'
      );
    }

    const available =
      segment.to.diff(
        segment.from,
        'minutes'
      ).minutes;

    if (remaining <= available) {
      return segment.from
        .plus({ minutes: remaining })
        .toUTC()
        .toISO();
    }

    remaining -= available;

    cursor =
      segment.to.plus({
        milliseconds: 1
      });
  }

  throw new Error(
    'Could not calculate followup working time'
  );
}

const event = $('Claim Due Events').item.json;
const task = $('Get Task — Start').item.json;
const resolved = $('Resolve Telegram Username').item.json;
const sent = $json;
const decision = $('Parse Agent Decision').item.json;

const eventId = bigint(event.event_id, 'event_id');
const dialogId = bigint(event.dialog_id, 'dialog_id');

const chatId =
  bigint(
    sent.chat_id ?? resolved.id,
    'telegram_chat_id'
  );

const telegramMessageId =
  bigint(sent.id, 'telegram_message_id');

const message = sql(decision.message);

const waitForUser = decision.wait_for_user === true;
const waitingFor =
  waitForUser
    ? sql(decision.waiting_for || 'ответ на первое сообщение')
    : '';

const followupAfter =
  Math.max(
    0,
    Math.floor(
      Number(task.followup_after_work_minutes ?? 0)
    )
  );

const maxFollowups =
  Math.max(
    0,
    Math.floor(
      Number(task.max_followups ?? 0)
    )
  );

const followupRunAt =
  waitForUser &&
  followupAfter > 0 &&
  maxFollowups > 0
    ? addWorkingMinutes(task, followupAfter)
    : null;

const nextActionSql =
  followupRunAt
    ? `'${sql(followupRunAt)}'::timestamptz`
    : 'NULL';

const scheduleFollowupSql =
  followupRunAt
