, schedule_followup AS (
  INSERT INTO agent_v3.events (
    dialog_id,
    event_type,
    run_at,
    status,
    payload
  )
  VALUES (
    ${dialogId},
    'followup',
    '${sql(followupRunAt)}'::timestamptz,
    'pending',
    jsonb_build_object(
      'airtable_task_id',
      '${sql(event.airtable_task_id)}',
      'airtable_dialog_id',
      '${sql(event.airtable_dialog_id)}',
      'waiting_for',
      '${waitingFor}',
      'followup_number',
      1,
      'origin_event_id',
      ${eventId}
    )
  )
  ON CONFLICT DO NOTHING
  RETURNING id
)
`
    : '';

const q = `
WITH update_dialog AS (
  UPDATE agent_v3.dialogs
  SET
    telegram_chat_id = ${chatId},
    status = '${waitForUser ? 'waiting_user' : 'active'}',
    waiting_for = ${waitForUser ? `'${waitingFor}'` : 'NULL'},
    followup_count = 0,
    started_at = COALESCE(started_at, NOW()),
    last_activity_at = NOW(),
    last_outbound_at = NOW(),
    next_action_at = ${nextActionSql},
    updated_at = NOW()
  WHERE id = ${dialogId}
  RETURNING id
),

insert_message AS (
  INSERT INTO agent_v3.messages (
    dialog_id,
    telegram_message_id,
    direction,
    sender_type,
    message_type,
    text,
    telegram_created_at,
    metadata
  )
  VALUES (
    ${dialogId},
    ${telegramMessageId},
    'outbound',
    'agent',
    'text',
    '${message}',
    NOW(),
    jsonb_build_object(
      'event_id',
      ${eventId},
      'source',
      'start_dialog'
    )
  )
  ON CONFLICT (
    dialog_id,
    telegram_message_id
  )
  WHERE telegram_message_id IS NOT NULL
  DO NOTHING
  RETURNING id
)
${scheduleFollowupSql}
, finish_event AS (
  UPDATE agent_v3.events
  SET
    status = 'done',
    processed_at = NOW(),
    locked_at = NULL,
    last_error = NULL,
    updated_at = NOW()
  WHERE id = ${eventId}
  RETURNING id
)

SELECT
  ${eventId}::bigint AS event_id,
  ${dialogId}::bigint AS dialog_id,
  '${sql(event.airtable_dialog_id)}'::text AS airtable_dialog_id,
  '${sql(event.airtable_task_id)}'::text AS airtable_task_id,
  ${chatId}::bigint AS telegram_chat_id,
  ${telegramMessageId}::bigint AS telegram_message_id,
  '${waitForUser ? 'Waiting user' : 'Active'}'::text AS airtable_status,
  '${waitingFor}'::text AS waiting_for,
  0::integer AS followup_count,
  ${nextActionSql} AS next_action_at;
`;

return [{
  json: {
    sql_query: q,
    event_id: event.event_id,
    dialog_id: event.dialog_id,
    airtable_dialog_id: event.airtable_dialog_id,
    airtable_task_id: event.airtable_task_id,
    telegram_chat_id: chatId,
    telegram_message_id: telegramMessageId,
    airtable_status:
      waitForUser ? 'Waiting user' : 'Active',
    waiting_for:
      waitForUser ? decision.waiting_for : '',
    followup_count: 0,
    next_action_at: followupRunAt,
    message: decision.message
  }
}];

