const event = $('Claim Due Events').item.json;
const sent = $json;
const decision = $('Parse Agent Decision').item.json;

function getTask() {
  if (event.event_type === 'process_inbound') {
    return $('Get Task — Inbound').item.json;
  }

  if (event.event_type === 'owner_answer') {
    return $('Get Task — Owner Answer').item.json;
  }

  if (event.event_type === 'followup') {
    return $('Get Task — Followup').item.json;
  }

  throw new Error(
    `No task source for event_type=${event.event_type}`
  );
}

const task = getTask();

const eventId = bigint(event.event_id, 'event_id');
const dialogId = bigint(event.dialog_id, 'dialog_id');
const telegramMessageId =
  bigint(sent.id, 'telegram_message_id');

const message = sql(decision.message);

/*
 * owner_answer is asynchronous.
 * It must add the clarification to the conversation WITHOUT
 * cancelling/changing the user-side waiting state, followup or topic.
 */
if (event.event_type === 'owner_answer') {
  const q = `
WITH update_dialog AS (
  UPDATE agent_v3.dialogs
  SET
    last_activity_at = NOW(),
    last_outbound_at = NOW(),
    updated_at = NOW()
  WHERE id = ${dialogId}
  RETURNING
    id,
    status,
    waiting_for,
    followup_count,
    next_action_at
),

insert_message AS (
  INSERT INTO agent_v3.messages (
    dialog_id,
    telegram_message_id,
    direction,
    sender_type,
    message_type,
    text,
    telegram_created_at,
    metadata
  )
  VALUES (
    ${dialogId},
    ${telegramMessageId},
    'outbound',
    'agent',
    'text',
    '${message}',
    NOW(),
    jsonb_build_object(
      'event_id',
      ${eventId},
      'source',
      'owner_answer_nonblocking'
    )
  )
  ON CONFLICT (
    dialog_id,
    telegram_message_id
  )
  WHERE telegram_message_id IS NOT NULL
  DO NOTHING
  RETURNING id
),

finish_event AS (
  UPDATE agent_v3.events
  SET
    status = 'done',
    processed_at = NOW(),
    locked_at = NULL,
    last_error = NULL,
    updated_at = NOW()
  WHERE id = ${eventId}
  RETURNING id
)

SELECT
  ${eventId}::bigint AS event_id,
  ${dialogId}::bigint AS dialog_id,
  '${sql(event.airtable_dialog_id)}'::text
    AS airtable_dialog_id,
  '${sql(event.airtable_task_id)}'::text
    AS airtable_task_id,
  ${telegramMessageId}::bigint
    AS telegram_message_id,

  CASE
    WHEN d.status = 'waiting_user'
      THEN 'Waiting user'
    WHEN d.status = 'waiting_owner'
      THEN 'Waiting owner'
    WHEN d.status = 'done'
      THEN 'Done'
    WHEN d.status = 'error'
      THEN 'Error'
    WHEN d.status = 'scheduled'
      THEN 'Scheduled'
    WHEN d.status = 'new'
      THEN 'New'
    ELSE 'Active'
  END::text AS airtable_status,

  COALESCE(d.waiting_for, '')::text
    AS waiting_for,

  COALESCE(d.followup_count, 0)::integer
