}

function optionName(v) {
  if (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v)
  ) {
    return v.name ?? String(v);
  }

  return String(v ?? '');
}

function multiNames(v) {
  if (!Array.isArray(v)) return [];
  return v.map(optionName).filter(Boolean);
}

function hhmm(v, fallback) {
  const m =
    String(v || fallback)
      .match(/^(\d{1,2}):(\d{2})/);

  if (!m) {
    throw new Error(`Invalid time: ${v}`);
  }

  return {
    h: Number(m[1]),
    m: Number(m[2])
  };
}

function addWorkingMinutes(task, minutes) {
  minutes =
    Math.max(
      0,
      Math.floor(
        Number(minutes || 0)
      )
    );

  if (minutes <= 0) {
    return null;
  }

  const zone =
    optionName(task.timezone) ||
    'Europe/Moscow';

  const daysRaw =
    multiNames(task.work_days);

  const days =
    daysRaw.length
      ? daysRaw
      : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];

  const dayMap = {
    Mon: 1,
    Tue: 2,
    Wed: 3,
    Thu: 4,
    Fri: 5,
    Sat: 6,
    Sun: 7
  };

  const allowed =
    new Set(
      days
        .map(x => dayMap[x])
        .filter(Boolean)
    );

  const start =
    hhmm(
      task.work_start,
      '09:00'
    );

  const end =
    hhmm(
      task.work_end,
      '19:00'
    );

  let cursor =
    $now.setZone(zone);

  let remaining =
    minutes;

  for (
    let guard = 0;
    guard < 500 && remaining > 0;
    guard++
  ) {
    let segment = null;

    for (
      let offset = -1;
      offset <= 370;
      offset++
    ) {
      const day =
        cursor
          .startOf('day')
          .plus({ days: offset });

      if (!allowed.has(day.weekday)) {
        continue;
      }

      let ws =
        day.set({
          hour: start.h,
          minute: start.m,
          second: 0,
          millisecond: 0
        });

      let we =
        day.set({
          hour: end.h,
          minute: end.m,
          second: 0,
          millisecond: 0
        });

      if (we <= ws) {
        we = we.plus({ days: 1 });
      }

      if (we <= cursor) {
        continue;
      }

      const from =
        cursor > ws
          ? cursor
          : ws;

      if (from < we) {
        segment = {
          from,
          to: we
        };

        break;
      }
    }

    if (!segment) {
      throw new Error(
        'Could not find next working window'
      );
    }

    const available =
      segment.to
        .diff(
          segment.from,
          'minutes'
        )
        .minutes;

    if (remaining <= available) {
      return segment.from
        .plus({
          minutes: remaining
        })
        .toUTC()
        .toISO();
    }

    remaining -= available;

    cursor =
      segment.to
        .plus({
          milliseconds: 1
        });
  }

  throw new Error(
    'Could not calculate followup working time'
  );
}

