            m.sender_type === 'agent'
              ? 'АССИСТЕНТ'
              : String(m.sender_type ?? '').toUpperCase()
          );

    const body =
      String(m.text ?? '').trim() ||
      `[${m.message_type ?? 'message'}]`;

    return `${who}: ${body}`;
  })
  .join('\n');

const factsText =
  facts.length
    ? facts.map(f => {
        const cat = f.category ? `[${f.category}] ` : '';
        return `- ${cat}${f.fact_text}`;
      }).join('\n')
    : '(подтверждённых фактов пока нет)';

return [{
  json: {
    ...event,

    agent_event: 'followup',

    task_name: task.Name_task ?? '',
    goal: task.goal ?? '',
    required_result: task.required_result ?? '',
    assistant_role: task.assistant_role ?? '',
    assistant_identity: task.assistant_identity ?? '',
    information_base: task.information_base ?? '',
    rules: task.rules ?? '',
    communication_style: task.communication_style ?? '',

    person_name: dialog.person_name ?? event.person_name ?? '',
    person_role: dialog.person_role ?? event.person_role ?? '',
    person_context: dialog.person_context ?? '',

    conversation_text:
      conversationText || '(история пуста)',

    facts_text: factsText,

    waiting_for_text:
      event.waiting_for ??
      dialog.waiting_for ??
      '',

    followup_count:
      Number(event.followup_count ?? 0),

    max_followups:
      Number(task.max_followups ?? 0),

    open_owner_requests_text:
      '(для followup не требуется)',

    allowed_actions:
      'send_message | no_action'
  }
}];

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}

function bigint(v, label) {
  const s = String(v ?? '').trim();
  if (!/^-?\d+$/.test(s)) {
    throw new Error(`${label} is not an integer: ${s}`);
  }
  return s;
}

const event = $('Claim Due Events').item.json;
const decision = $('Parse Agent Decision').item.json;

const eventId = bigint(event.event_id, 'event_id');
const dialogId = bigint(event.dialog_id, 'dialog_id');

const clearWaiting =
  decision.clear_waiting === true;

const status =
  clearWaiting
    ? 'active'
    : 'waiting_user';

const airtableStatus =
  clearWaiting
    ? 'Active'
    : 'Waiting user';

const q = `
WITH cancel_followups AS (
  UPDATE agent_v3.events
  SET
    status = 'cancelled',
    locked_at = NULL,
    updated_at = NOW()
  WHERE dialog_id = ${dialogId}
    AND event_type = 'followup'
    AND status = 'pending'
  RETURNING id
),

update_dialog AS (
  UPDATE agent_v3.dialogs
  SET
    status = '${status}',
    waiting_for =
      ${clearWaiting ? 'NULL' : 'waiting_for'},
    next_action_at = NULL,
    updated_at = NOW()
  WHERE id = ${dialogId}
  RETURNING id
),

finish_event AS (
  UPDATE agent_v3.events
  SET
    status = 'done',
    processed_at = NOW(),
    locked_at = NULL,
    last_error = NULL,
    updated_at = NOW()
  WHERE id = ${eventId}
  RETURNING id
)

SELECT
  ${eventId}::bigint AS event_id,
  ${dialogId}::bigint AS dialog_id,
  '${sql(event.airtable_dialog_id)}'::text AS airtable_dialog_id,
  '${sql(event.airtable_task_id)}'::text AS airtable_task_id,
  '${airtableStatus}'::text AS airtable_status,
  ${clearWaiting ? "''::text" : "COALESCE((SELECT waiting_for FROM agent_v3.dialogs WHERE id = " + dialogId + "), '')::text"} AS waiting_for,
  NULL::timestamptz AS next_action_at,
  ${Math.max(0, Number(event.followup_count ?? 0))}::integer AS followup_count;
`;

return [{
  json: {
    sql_query: q,
    airtable_dialog_id:
      event.airtable_dialog_id,
    airtable_status: airtableStatus,
    waiting_for:
      clearWaiting ? '' : String(event.waiting_for ?? ''),
    next_action_at: null,
    followup_count:
      Math.max(0, Number(event.followup_count ?? 0)),
    reason: decision.reason ?? ''
  }
}];

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}

function bigint(v, label) {
  const s = String(v ?? '').trim();

  if (!/^-?\d+$/.test(s)) {
    throw new Error(`${label} is not an integer: ${s}`);
  }

  return s;
}

const event =
  $('Claim Due Events').item.json;

const decision =
  $('Parse Agent Decision').item.json;

const eventId =
  bigint(event.event_id, 'event_id');

const dialogId =
  bigint(event.dialog_id, 'dialog_id');

const summary =
  sql(decision.summary);

const finalResult =
  sql(decision.final_result);

const completionReason =
  sql(decision.completion_reason);

const finalMessage =
  String(decision.message ?? '').trim();

let telegramMessageId = null;

if (finalMessage) {
  telegramMessageId =
    bigint(
      $json.id,
      'telegram_message_id'
    );
}

const insertMessageSql =
  finalMessage
    ? `
, insert_final_message AS (
  INSERT INTO agent_v3.messages (
    dialog_id,
    telegram_message_id,
    direction,
    sender_type,
    message_type,
    text,
    telegram_created_at,
    metadata
  )
  VALUES (
    ${dialogId},
    ${telegramMessageId},
    'outbound',
    'agent',
    'text',
    '${sql(finalMessage)}',
    NOW(),
    jsonb_build_object(
      'event_id',
      ${eventId},
      'source',
      'complete_dialog',
      'completion_reason',
      '${completionReason}'
    )
  )
  ON CONFLICT (
    dialog_id,
    telegram_message_id
  )
  WHERE telegram_message_id IS NOT NULL
  DO NOTHING
  RETURNING id
)
`
    : '';

const q = `
WITH cancel_pending_events AS (
  UPDATE agent_v3.events
  SET
    status = 'cancelled',
    locked_at = NULL,
    updated_at = NOW()
  WHERE dialog_id = ${dialogId}
    AND id <> ${eventId}
    AND status = 'pending'
  RETURNING id
),

cancel_owner_requests AS (
  UPDATE agent_v3.owner_requests
  SET
    status = 'cancelled',
    cancelled_at = COALESCE(cancelled_at, NOW()),
    updated_at = NOW()
  WHERE dialog_id = ${dialogId}
    AND status = 'open'
  RETURNING id
),

update_dialog AS (
  UPDATE agent_v3.dialogs
  SET
    status = 'done',
    waiting_for = NULL,
    summary = '${summary}',
    final_result = '${finalResult}',
    next_action_at = NULL,
    finished_at = NOW(),
    last_activity_at = NOW(),
    last_outbound_at =
      CASE
        WHEN ${finalMessage ? 'TRUE' : 'FALSE'}
        THEN NOW()
        ELSE last_outbound_at
      END,
    metadata =
      COALESCE(metadata, '{}'::jsonb)
      ||
      jsonb_build_object(
        'completion_reason',
        '${completionReason}',
        'completion_notify_pending',
        TRUE,
        'completion_notify_created_at',
        NOW()
      ),
    updated_at = NOW()
  WHERE id = ${dialogId}
  RETURNING id
)
${insertMessageSql}
, finish_event AS (
  UPDATE agent_v3.events
  SET
    status = 'done',
    processed_at = NOW(),
    locked_at = NULL,
    last_error = NULL,
    updated_at = NOW()
  WHERE id = ${eventId}
  RETURNING id
),

task_result AS (
  SELECT
    string_agg(
      COALESCE(
        NULLIF(d.person_name, ''),
        NULLIF(d.telegram_username, ''),
        'Собеседник #' || d.id::text
      )
      || ': '
      ||
      CASE
        WHEN d.id = ${dialogId}
        THEN '${finalResult}'
        ELSE COALESCE(
          NULLIF(d.final_result, ''),
          NULLIF(d.summary, ''),
          CASE
            WHEN d.status = 'done'
            THEN 'Диалог завершён'
            ELSE 'В работе'
          END
        )
      END,
      E'\\n'
      ORDER BY d.id
    ) AS result
  FROM agent_v3.dialogs d
  WHERE d.airtable_task_id =
        '${sql(event.airtable_task_id)}'
)

SELECT
  ${eventId}::bigint AS event_id,
  ${dialogId}::bigint AS dialog_id,

  '${sql(event.airtable_dialog_id)}'::text
    AS airtable_dialog_id,

  '${sql(event.airtable_task_id)}'::text
    AS airtable_task_id,

  '${summary}'::text AS summary,
  '${finalResult}'::text AS final_result,
  '${completionReason}'::text AS completion_reason,

  NOW() AS finished_at,

  COALESCE(
    (SELECT result FROM task_result),
    '${finalResult}'
  ) AS task_result;
`;

return [{
  json: {
    sql_query: q,

    airtable_dialog_id:
      event.airtable_dialog_id,

    airtable_task_id:
      event.airtable_task_id,

    summary:
      decision.summary,

    final_result:
      decision.final_result,

    completion_reason:
      decision.completion_reason,

    final_message:
      finalMessage
  }
}];

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}

function optionName(v) {
  if (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v)
  ) {
    return String(v.name ?? '');
  }

  return String(v ?? '');
}

const task = $json;

const event =
  $('Claim Due Events')
    .item
    .json;

const rawStatus =
  optionName(
    task.Status ??
    task.status
  )
    .trim();

const taskStatus =
  rawStatus === 'Active'
    ? 'Active'
    : rawStatus === 'Done'
      ? 'Done'
      : 'Paused';

const eventId =
  Number(event.event_id);

if (!Number.isFinite(eventId)) {
  throw new Error(
    'event_id is missing in task status guard'
  );
}

const taskId =
  String(
    event.airtable_task_id ??
    task.id ??
    ''
  ).trim();

if (!taskId) {
  throw new Error(
    'airtable_task_id is missing in task status guard'
  );
}

let guardSql = '';

if (taskStatus === 'Paused') {
  guardSql = `
UPDATE agent_v3.events
SET
  status = 'pending',

  locked_at = NULL,

  attempts =
    GREATEST(
      attempts - 1,
      0
    ),

  payload =
    jsonb_set(
      jsonb_set(
        jsonb_set(
          COALESCE(
            payload,
            '{}'::jsonb
          ),
          '{deferred_by_task_status}',
          to_jsonb('Paused'::text),
          true
        ),
        '{deferred_original_run_at}',
        to_jsonb(run_at::text),
        true
      ),
      '{deferred_at}',
      to_jsonb(NOW()::text),
      true
    ),

  -- Sentinel date:
  -- Event Runner will not reclaim it
  -- while the task stays Paused.
  run_at =
    '9999-12-31 23:59:59+00'
      ::timestamptz,

  updated_at = NOW()

WHERE
  id = ${eventId}

  AND
  status = 'processing'

RETURNING
  id AS event_id,
  dialog_id,
  event_type,
  status,
  run_at,
  payload;
`;
}

if (taskStatus === 'Done') {
  guardSql = `
WITH cancel_current AS (
  UPDATE agent_v3.events
  SET
    status = 'cancelled',
    locked_at = NULL,
    last_error =
      'Task status = Done',
    updated_at = NOW()
  WHERE
    id = ${eventId}
    AND
    status = 'processing'
  RETURNING id
),

cancel_pending AS (
  UPDATE agent_v3.events e
  SET
    status = 'cancelled',
    locked_at = NULL,
    last_error =
      'Task status = Done',
    updated_at = NOW()
  FROM agent_v3.dialogs d
  WHERE
    e.dialog_id = d.id

    AND
    d.airtable_task_id =
      '${sql(taskId)}'

    AND
    e.status = 'pending'
  RETURNING e.id
)

SELECT
  ${eventId}::bigint AS event_id,
  '${sql(taskId)}'::text
    AS airtable_task_id,
  'Done'::text
    AS task_status,
  (
    SELECT COUNT(*)
    FROM cancel_current
  )::integer
    AS cancelled_current,
  (
    SELECT COUNT(*)
    FROM cancel_pending
  )::integer
    AS cancelled_pending;
`;
}

return [{
  json: {
    ...event,
    ...task,

    airtable_task_id:
      taskId,

    task_status_raw:
      rawStatus,

    task_status:
      taskStatus,

    task_is_active:
      taskStatus === 'Active',

    guard_sql:
      guardSql
  }
}];

